\title{\Large $\ $ \bf Thyroid Nodule Segmentation in Ultrasound Images with Conformal Uncertainty Estimation}
\author{\large Francesco Teodori$^{*, 1}$, Pierpaolo Brutti$^{1}$, and Umberto Ferraro Petrillo$^{1}$}
\address{\footnotesize $\ $$^1$ Department of Statistical Sciences, Sapienza University of Rome, Rome, Italy. 
