\section{Proof of Lemma \ref{lemma_-1}}\label{appendix_-1}
Define the random variable $ X = \sum_{n=0}^{M-1} e^{j\delta_n} = X_R+jX_I$, where the real and imaginary components are the random variables $X_R=\sum_{n=0}^{M-1}\cos(\delta_n)$ and $X_I=\sum_{n=0}^{M-1}\sin(\delta_n)$, respectively.
Then, $\nu = \frac{|X|^2}{M^2} = \frac{X_R^2+X_I^2}{M^2}$. Since $\delta_n\sim\mathrm{i.i.d.}\ \mathrm{Unif}[0,2\pi)$, we have $\mathbb E[\cos(\delta_n)]
 =
 \mathbb E[\sin(\delta_n)]
 =
 0$, $\mathrm{Var}(\cos(\delta_n))
 =
 \mathrm{Var}(\sin(\delta_n))
 =
 \frac{1}{2}$, and $\mathbb E[\cos(\delta_n)\sin(\delta_n)]
 =
 0$. Therefore, by the Berry-Esseen theorem \cite{vershynin2026friendly},
\begin{align}
 \left(
 \frac{X_R}{\sqrt{M/2}},
 \frac{X_I}{\sqrt{M/2}}
 \right)
 \xrightarrow{d}
 (Z_1,Z_2),
\end{align}
with an approximation error of order $\mathcal O(1/\sqrt{M})$, where $Z_1$ and $Z_2$ are independent standard normal random variables.
It follows that
\begin{align}
 M\nu
 =
 \frac{1}{2}
 \left[
 \left(\frac{X_R}{\sqrt{M/2}}\right)^2
 +
 \left(\frac{X_I}{\sqrt{M/2}}\right)^2
 \right]
 \xrightarrow{d}
 \frac{1}{2}(Z_1^2+Z_2^2).
\end{align}
Since $Z_1^2+Z_2^2\sim\chi_2^2$, we have $\frac{1}{2}(Z_1^2+Z_2^2) \sim \mathrm{Exp}(1)$. Thus, for large $M$, $M\nu$ is approximately exponentially distributed with unit rate, or equivalently, $\nu$ is approximately exponentially distributed with rate $M$. Hence, $F_\nu(\gamma) = 1-e^{-M\gamma} + \mathcal O\left(\frac{1}{\sqrt{M}}\right)$,
which proves the lemma.
\section{Proof of Lemma \ref{lemma_rp_high_gain}}\label{appendix_rp_highgain}
Let $\epsilon=1-\gamma$. From \eqref{define_gain_RP}, $\nu = \frac{1}{M^2} \left\lvert \sum_{n=0}^{M-1} e^{j\delta_n} \right\rvert^2$, where $\boldsymbol{\delta}=[\delta_0,\ldots,\delta_{M-1}]^{\mathsf T}$
is uniformly distributed over $[0,2\pi)^M$. Expanding the squared
magnitude gives $\nu = 1 - \frac{1}{M^2} \sum_{m,n} 2\sin^2\left(\frac{\delta_m-\delta_n}{2}\right).$
Define the high-gain event $\mathcal D_\epsilon \triangleq \{ \nu \geq 1-\epsilon \}$. Equivalently,
\begin{align}
 \mathcal D_\epsilon
 =
 \left\{
 \sum_{m,n}
 2\sin^2\left(\frac{\delta_m-\delta_n}{2}\right)
 \leq
 M^2\epsilon
 \right\}.
\end{align}
Since all terms in the summation are nonnegative, on
$\mathcal D_\epsilon$ we have $\left| \sin\left(\frac{\delta_m-\delta_n}{2}\right) \right| \leq \frac{M}{\sqrt{2}}\sqrt{\epsilon}, \forall m,n$. Thus, for $M^2\epsilon\ll1$, all phases are close to a common phase
modulo $2\pi$. Equivalently, after unwrapping the phases around this
common phase, $|\delta_m-\delta_n| = \mathcal O(\sqrt{\epsilon}), \forall m,n.$ For any fixed $\rho\in(0,1/2)$ and sufficiently small phase differences,
\begin{align}
 \left(\frac{1}{2}-\rho\right)x^2
 \leq
 2\sin^2\left(\frac{x}{2}\right)
 \leq
 \left(\frac{1}{2}+\rho\right)x^2 .
\end{align}
Therefore, the event $\mathcal D_\epsilon$ is sandwiched as
\begin{align}
 &
 \left\{
 \left(\frac{1}{2}+\rho\right)
 \sum_{m,n}(\delta_m-\delta_n)^2
 \leq
 M^2\epsilon
 \right\}
 \subseteq
 \mathcal D_\epsilon
 \nonumber
 &\hspace{1.4cm}
 \subseteq
 \left\{
 \left(\frac{1}{2}-\rho\right)
 \sum_{m,n}(\delta_m-\delta_n)^2
 \leq
 M^2\epsilon
 \right\}.
\end{align}
Now define $\bar{\delta}
 =
 \frac{1}{M}
 \sum_{n=0}^{M-1}\delta_n$ and $\widetilde{\boldsymbol{\delta}}
 =
 \boldsymbol{\delta}
 -
 \bar{\delta}\mathbf 1.$
Using the identity
\begin{align}
 \sum_{m,n}
 (\delta_m-\delta_n)^2
 =
 2M
 \sum_{n=0}^{M-1}
 (\delta_n-\bar{\delta})^2
 =
 2M
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|^2,
\end{align}
the sandwich becomes
\begin{align}
 \left\{
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|^2
 \leq
 \frac{M\epsilon}{1+2\rho}
 \right\}
 \subseteq
 \mathcal D_\epsilon
 \subseteq
 \left\{
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|^2
 \leq
 \frac{M\epsilon}{1-2\rho}
 \right\}.
\end{align}
The centered vector $\widetilde{\boldsymbol{\delta}}$ lies in the
$(M-1)$-dimensional hyperplane $\mathcal H
 =
 \left\{
 \mathbf x\in\mathbb R^M:
 \mathbf 1^{\mathsf T}\mathbf x=0
 \right\}.$ The remaining degree of freedom is the common phase. Since the gain is
invariant to a common phase rotation, this degree of freedom contributes
a factor equal to the length of the diagonal circle, namely
$2\pi\sqrt{M}$. Hence, for a ball of radius $R$ in $\mathcal H$,
\begin{align}
 \Pr\left\{
 \left\|
