 =
 \sqrt{M\epsilon}
 \left(1+\mathcal O(\epsilon)\right).$ Therefore,
\begin{align}
 \Pr\{\nu\geq 1-\epsilon\}
 =
 C_M
 \epsilon^{\frac{M-1}{2}}
 +
 \mathcal O\left(
 \epsilon^{\frac{M+1}{2}}
 \right).
\end{align}
Substituting $\epsilon=1-\gamma$ yields
\begin{align}
 F_\nu(\gamma)
 =
 1
 -
 C_M
 (1-\gamma)^{\frac{M-1}{2}}
 +
 \mathcal O\left(
 (1-\gamma)^{\frac{M+1}{2}}
 \right),
\end{align}
which proves the lemma.
\section{Proof of Lemma \ref{lemma_0}}\label{appendix_0}
After changing variables in \eqref{lemma_eqn} using \(\ell=n-m\), the beamforming gain can be written as
\begin{align}
 \nu_k =
 \frac{1}{M^2}
 \sum_{\ell=-M+1}^{M-1}
 \sum_{m=\max\{0,-\ell\}}^{\min\{M-1,M-1-\ell\}}
 e^{j\pi\left(A(2m\ell+\ell^2)+(\theta_k-\theta_t)\ell\right)}.
\end{align}
We separate the summation into the three cases \(\ell<0\), \(\ell=0\), and \(\ell>0\). For \(\ell=0\), the exponential term is equal to \(1\), and hence the inner sum contributes $\sum_{m=0}^{M-1} 1 = M$.
Therefore, $\nu_k = \frac{\zeta_1 + M + \zeta_2}{M^2}$, where
\begin{align}
 \zeta_1
 &\triangleq
 \sum_{\ell=-M+1}^{-1}
 \sum_{m=-\ell}^{M-1}
 e^{j\pi\left(A(2m\ell+\ell^2)+\ell(\theta_k-\theta_t)\right)},
 \zeta_2
 &\triangleq
 \sum_{\ell=1}^{M-1}
 \sum_{m=0}^{M-1-\ell}
 e^{j\pi\left(A(2m\ell+\ell^2)+\ell(\theta_k-\theta_t)\right)}.
\end{align}
We first simplify \(\zeta_1\). Letting \(\ell \mapsto -\ell\), we obtain
\begin{align}
 \zeta_1
 =
 \sum_{\ell=1}^{M-1}
 e^{j\pi\left(A\ell^2-\ell(\theta_k-\theta_t)\right)}
 \sum_{m=\ell}^{M-1} e^{-j2\pi A\ell m}.
\end{align}
The inner sum is geometric, and applying the finite geometric-series identity yields
\begin{align}
 \sum_{m=\ell}^{M-1} e^{-j2\pi A\ell m}
 =
 e^{-j\pi A\ell(M+\ell-1)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Substituting this into the expression for \(\zeta_1\) gives
\begin{align}\label{delta_1_simplify_rewrite}
 \zeta_1
 =
 \sum_{\ell=1}^{M-1}
 e^{-j\pi \ell\big(A(M-1)+\theta_k-\theta_t\big)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Similarly, for \(\zeta_2\),
\begin{align}
 \zeta_2
 =
 \sum_{\ell=1}^{M-1}
 e^{j\pi\left(A\ell^2+\ell(\theta_k-\theta_t)\right)}
 \sum_{m=0}^{M-1-\ell} e^{j2\pi A\ell m}.
\end{align}
Again using the geometric-series identity, the inner sum becomes
\begin{align}
 \sum_{m=0}^{M-1-\ell} e^{j2\pi A\ell m}
 =
 e^{j\pi A\ell(M-1-\ell)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Hence,
\begin{align}\label{delta_2_simplify_rewrite}
 \zeta_2
 =
 \sum_{\ell=1}^{M-1}
 e^{j\pi \ell\big(A(M-1)+\theta_k-\theta_t\big)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Finally, substituting \eqref{delta_1_simplify_rewrite} and \eqref{delta_2_simplify_rewrite} into $\nu_k = \frac{\zeta_1+M+\zeta_2}{M^2}$, and using $e^{j\theta} + e^{-j\theta} = 2\cos(\theta)$, we obtain \eqref{nu_A_B}, which proves the lemma.
\section{Proof of Lemma \ref{lemma_1} }\label{appendix_A}
Define $u(p) \triangleq \frac{p}{\sin(\pi Ap)}$. Then, from \eqref{define_f}, $f_p(\theta_t, r_t) = u(p)\sin(\pi(M-p)Ap)$. We first approximate \(u(p)\). From \eqref{define_A_range} $A(\theta_t,r_t) \in \left[0, A_{\max} \right]$. This bound shows that the maximum possible value of $A(\theta_t,r_t)$ decreases as $M$ increases. Therefore, over the entire considered user region, $A(\theta_t,r_t)$ is small for large $M$, which justifies the use of small-angle expansion.
Using $\sin x = x + \mathcal{O}(x^3)$, with \(x=\pi Ap\), we obtain $\sin(\pi Ap) = \pi Ap\left(1+\mathcal{O}\left(A^2p^2\right)\right)$. Substituting this into \(u(p)\) gives $u(p) = \frac{1}{\pi A \left(1+\mathcal{O}\left(A^2p^2\right)\right)}$. Since $p\in [1,M-1]$ and $A \in \left[0, A_{\max} \right]$, we have $A^2p^2 \leq A_{\max}^2 (M-1)^2 = \mathcal{O}(\frac{1}{M})$. Thus, for all \(p\in\{1,2,\ldots,M-1\}\),
\begin{align}
 u(p)
 = \frac{1}{\pi A}\left(1+\mathcal{O}\left(\frac{1}{M}\right)\right).
\end{align}
Hence, for large \(M\), \(u(p)\) is approximately constant over the entire range of interest. Next, notice that the second factor in $f_p(\theta_t, r_t)$ is exactly symmetric under the reflection \(p \mapsto M-p\).
Specifically, $\sin(\pi(M-(M-p))A(M-p)) = \sin(\pi(M-p)Ap)$. Hence, the term $\sin(\pi(M-p)Ap)$ is exactly symmetric about $p = M/2$. Therefore, for large \(M\), $f_p(\theta_t, r_t)$ is approximately even about \(p=M/2\), which proves the lemma.
\section{Proof of Lemma \ref{lemma_2} }\label{appendix_B}
From Lemma \ref{lemma_1}, the function $f_p(\theta_t, r_t)$ is approximately even about $p= \frac{M}{2}$ for large $M$. Therefore, in \eqref{define_derivative},
the summation approximately cancels if $g_p(\theta_k, \theta_t, r_t)$ is odd about \(p=M/2\). Define $C \triangleq A(M-1)+\theta_k-\theta_t$ so that $ g_p(\theta_k, \theta_t, r_t) =\sin(\pi p C)$. For $ g_p(\theta_k, \theta_t, r_t) $ to be odd about $p=M/2$, we require $g_{M-p}(\theta_k, \theta_t, r_t)=-g_p(\theta_k, \theta_t, r_t)$. If $C=\frac{2b}{M}, b\in\mathbb Z$,
then $\pi MC=2b\pi$, and hence $g_{M-p}(\theta_k, \theta_t, r_t) = \sin\left(2b\pi-\pi pC\right) = -g_p(\theta_k, \theta_t, r_t)$. Thus, $g_p(\theta_k, \theta_t, r_t)$ is odd about $p=M/2$ for $\theta_k^{(b)} = \theta_t-A(M-1)+\frac{2b}{M}, b\in\mathbb Z$.

To quantify the residual, write
$
h(p)\triangleq \sin(\pi A p(M-p)).
$
Since
$
\frac{p}{\sin(\pi Ap)} = \frac{1}{\pi A} + \mathcal O(Ap^2)$, we have $ f_p(\theta_t,r_t) = \frac{h(p)}{\pi A} + h(p)\mathcal O(Ap^2)$. Since the first term is exactly even, only the residual contributes. Since $|h(p)|\leq1$ and $|g_p(\theta_k,\theta_t,r_t)|\leq1$, from \eqref{define_derivative},
$ \left. \frac{\partial \nu_k}{\partial \theta_k} \right|_{\theta_k=\theta_k^{(b)}} = \mathcal O(AM)$.
Since $A\leq A_{\max}=\mathcal O(M^{-3/2})$, the derivative is $\mathcal O(M^{-1/2})$. Hence, $\theta_k^{(b)}$ is an approximate stationary direction for large $M$.
\section{Proof of Lemma \ref{lemma_3} }\label{appendix_C}
From Lemma \ref{lemma_2}, the approximate stationary far-field directions of the RFF gain are $\theta_k^{(b)} = \theta_t - (M-1)A(\theta_t,r_t) + \frac{2b}{M}, b \in \mbb{N}_{0}$. 
Recall from \eqref{gain_define_critical_points},
\begin{align}
 G_b(A)
 =
 \frac{1}{M}
 +
 \frac{2}{M^2}
 \sum_{p=1}^{M-1}
 \cos\left(\pi p\frac{2b}{M}\right)
 \frac{\sin(\pi(M-p)Ap)}{\sin(\pi Ap)}.
\end{align}
We can rewrite $G_{b}(A)$ by substituting the $b$th candidate into the gain expression in \eqref{Y_k_original} as
\begin{align}
 G_b(A)
 =
 \frac{1}{M^2}
 \left|
 \sum_{n=0}^{M-1}
 e^{j\pi A(n^2-(M-1)n)}
 e^{j2\pi b n/M}
 \right|^2 .
\end{align}
The natural scaling of the curvature parameter is obtained from the quadratic phase term $\pi A n^2$. Since the largest antenna index is of order $M$, the total quadratic phase variation across the array is of order $AM^2$. Therefore, we define the scaled curvature parameter $\tau \triangleq AM^2.$ We now set $A=\tau/M^2$ and $x_n=n/M$. Then $A(n^2-(M-1)n) = \tau(x_n^2-x_n) + \frac{\tau x_n}{M}$. Hence, for fixed $\tau$ and fixed candidate index $q$,
\begin{align}
 e^{j \pi A(n^2 - (M-1)n)} e^{j 2 \pi b n/M} = e^{j \pi (\tau (x_n^2 - x_n) + 2 b x_n)} e^{j \pi \tau x_n/M}.
\end{align}
Since $e^{j \pi \tau x_n/M} = 1 + \mathcal{O}(1/M)$ for all $x_n \in [0,1]$, we get
\begin{align}
 \frac{1}{M}
 \sum_{n=0}^{M-1}
 &e^{j\pi A(n^2-(M-1)n)}
 e^{j2\pi b n/M}
 = \notag 
 &\frac{1}{M}
 \sum_{n=0}^{M-1}
 e^{j\pi(\tau(x_n^2-x_n)+2 b x_n)}
 +
 \mathcal O\left(\frac{1}{M}\right).
\end{align}
The summation on the right-hand side is a Riemann sum. Therefore,
\begin{align}
 \frac{1}{M}
 \sum_{n=0}^{M-1}
 e^{j\pi A(n^2-(M-1)n)}
 e^{j2\pi b n/M}
 \to
 \int_0^1
 e^{j\pi(\tau(x^2-x)+2 b x)}
 dx
\end{align}
as $M\to\infty$. Therefore, $G_b\left(\frac{\tau}{M^2}\right)
 \to
 \mathcal G_b(\tau)$,
where
\begin{align}\label{define_G_q_alpha}
 \mathcal G_b(\tau)
 \triangleq
 \left|
 \int_0^1
 e^{j\pi(\tau(x^2-x)+2bx)}
 dx
 \right|^2.
\end{align}
The gain expression in \eqref{define_G_q_alpha} has a useful interpretation at $\tau = 0$. For $b=0$, $\mathcal{G}_{0}(0) =1$. For $b \geq 1 $, $\mathcal{G}_{q}(0) = 0$. Thus, when the near-field curvature is negligible, the candidate $q = 0$ is optimal. The integral in \eqref{define_G_q_alpha} can be expressed using the Fresnel integrals. Define $C(u)
 =
 \int_0^u
 \cos\left(\frac{\pi t^2}{2}\right)dt$ and $S(u)
 =
 \int_0^u
 \sin\left(\frac{\pi t^2}{2}\right)dt$. Completing the square in \eqref{define_G_q_alpha} gives
\begin{align}\label{fresnel_gain}
 \mathcal G_b(\tau)
 =
 \frac{1}{2\tau}
 \left[
 \left(C(u_b^+)-C(u_b^-)\right)^2
 +
 \left(S(u_b^+)-S(u_b^-)\right)^2
 \right],
\end{align}
where $u_b^-
 =
 -\sqrt{\frac{\tau}{2}}
 +
 \frac{\sqrt{2}b}{\sqrt{\tau}}$ and $u_b^+
 =
 \sqrt{\frac{\tau}{2}}
 +
 \frac{\sqrt{2}b}{\sqrt{\tau}}$.
For each $b \geq 1$, define $\tau_{\mathrm{peak},b}$ as the first local maximum of $\mathcal{G}_{b}(\tau)$. Numerical calculation of \eqref{fresnel_gain} gives
\begin{align}
\begin{array}{c|c|c}
b
&
\tau_{\mathrm{peak},b}
&
\mathcal G_b(\tau_{\mathrm{peak},b})

\hline
1 & 5.28818 & 0.27533 
2 & 8.34186 & 0.17585 
3 & 11.13386 & 0.13140 
4 & 13.79617 & 0.10566 
5 & 16.37723 & 0.08871
\end{array}
\end{align}
Thus, the first local maximum shifts to larger values of $\tau$ as $b$ increases. This shows that higher order candidates become relevant only for larger values of $A(\theta_t,r_t)$. This makes intuitive sense because a larger $A(\theta_t,r_t)$ corresponds to a higher mismatch and a significant beam-split gain pattern.
We now define the transition points. Let $\beta_b$, with $\beta_0 = 0$, denote the scaled transition values corresponding to the sequence $\{ A_{\textrm{th},b} \}$, i.e., $A_{\textrm{th},b} = \frac{\beta_b}{M^2}$. Equivalently, $\beta_b$ is the value of $\tau$ that satisfies $\mathcal{G}_{b-1}(\beta_b) = \mathcal{G}_{b}(\beta_b).$
Numerically evaluating $\{ A_{\textrm{th},b} \}$ from \eqref{define_B}, we get
\begin{align}
\beta_1=4.72317,\quad
\beta_2=7.78690,\quad
\beta_3=10.58573.
\end{align}
We first consider the interval $\beta_1 \leq \tau \leq \beta_2$. The relevant scaled values are
\begin{align}
 \beta_1=4.72317,
 \quad \tau_{\mathrm{peak},1}=5.28818,
 \quad
 \beta_2=7.78690.
\end{align}
The gains using \eqref{fresnel_gain} at these values are
\begin{align}
\begin{array}{c|c|c|c}
b
&
\mathcal G_b(\beta_1)
&
\mathcal G_b(\tau_{\mathrm{peak},1})
&
\mathcal G_b(\beta_2)

\hline
0 & 0.26825 & 0.19072 & 0.08540 
1 & 0.26825 & 0.27533 & 0.17253 
2 & 0.07458 & 0.09642 & 0.17253 
3 & 0.01611 & 0.02308 & 0.07466 
4 & 0.00414 & 0.00598 & 0.02405 
5 & 0.00140 & 0.00197 & 0.00773
\end{array}
\end{align}
At the left endpoint $\beta_1$, the candidates $b=0$ and $b=1$ tie. At the right endpoint $\beta_2$, the candidates $b=1$ and $b=2$ tie. Over this interval, the previous candidate $b=0$ is decreasing, while the higher-order candidates $b \geq 2$ have their first local maxima outside the interval and remain below $b = 1$, with $b = 2$ only tying at $\beta_2$. Therefore, $b = 1$ gives the largest gain on $\beta_1 \leq \tau \leq \beta_2$.
Similarly, consider the interval $\beta_2 \leq \tau \leq \beta_3$. The relevant scaled values are
\begin{align}
 \beta_2=7.78690,
 \quad
 \tau_{\mathrm{peak},2}=8.34186,
 \quad
 \beta_3=10.58573.
\end{align}
The gains using \eqref{fresnel_gain} at these values are
\begin{align}
\begin{array}{c|c|c|c}
b
&
\mathcal G_b(\beta_2)
&
\mathcal G_b(\tau_{\mathrm{peak},2})
&
\mathcal G_b(\beta_3)

\hline
0 & 0.08540 & 0.09656 & 0.13203 
1 & 0.17253 & 0.13865 & 0.06056 
2 & 0.17253 & 0.17585 & 0.12940 
3 & 0.07466 & 0.08866 & 0.12940 
4 & 0.02405 & 0.03099 & 0.06838 
5 & 0.00773 & 0.01019 & 0.02736
\end{array}
\end{align}
At the left endpoint $\beta_2$, the candidates $b=1$ and $b=2$ tie. At the right endpoint $\beta_3$, the candidates $b=2$ and $b=3$ tie. Over this interval, the previous candidate $b=1$ is decreasing, while the higher-order candidates $b \geq 3$ have their first local maxima outside the interval and remain below $b=2$, with $b=3$ only tying at $\beta_3$. Therefore, $b=2$ gives the largest gain on $\beta_2 \leq \tau \leq \beta_3$, except on the sub-interval $(10.50374,10.81127)$ where $\mathcal{G}_0(\tau)$ dominates. This is the exception noted in Remark $\ref{remark_execption}$.
The same pattern is observed for subsequent intervals by numerically evaluating the gains. Hence, for large $M$, if $\beta_{b^{\star}} \leq AM^2 \leq \beta_{b^{\star}+1}$,
or equivalently $A_{\textrm{th},b^{\star}} \leq A \leq A_{\textrm{th},b^{\star}+1}$, then the maximizing far-field direction is $\theta_k^{(b^{\star})}$, up to the exception noted above. Substituting the direction $\theta_k^{(b^{\star})}$ into \eqref{nu_A_B} gives \eqref{max_ff_cb}. This proves the large-$M$ approximation.
\section{Proof of Lemma \ref{lemma_nf}}\label{appendix_nf}
Define the phase difference vector $\boldsymbol{\xi} \triangleq [\xi_0,\ldots,\xi_{M-1}]^{\mathsf T}$, where $\xi_n = \frac{2\pi}{\lambda} \left(r^{(n)}(\theta_k,r_k) - r^{(n)}(\theta_t,r_t) \right)$. Then, the beamforming gain of the $k$-th RNF codeword is $\nu_k = \frac{1}{M^2} \left| \sum_{n=0}^{M-1} e^{-j\xi_n} \right|^2$. Let $\Delta\theta=\theta_k-\theta_t$, $\Delta r=r_k-r_t$, and $ \mbf{o} = \begin{bmatrix} \Delta\theta \, \Delta r \end{bmatrix}^{\mathsf{T}}$. For small offsets around $(\theta_t,r_t)$, a first-order Taylor expansion of the phase map gives $\boldsymbol{\xi} = \mathbf J \mbf{o} + \mathcal O(\| \mbf{o} \|^2)$,
where $\mathbf J\in\mathbb R^{M\times 2}$ is the Jacobian of the phase vector with respect to $(\theta,r)$, evaluated at $(\theta_t,r_t)$.
Using the second-order Taylor expansion $e^{-j\xi_n} = 1-j\xi_n-\frac{\xi_n^2}{2} + \mathcal O(\xi_n^3)$, we obtain
\begin{align}
 \sum_{n=0}^{M-1}e^{-j\xi_n}
 =
 M
 -
 j\sum_{n=0}^{M-1}\xi_n
 -
 \frac{1}{2}\sum_{n=0}^{M-1}\xi_n^2
 +
 \mathcal O(\|\boldsymbol{\xi}\|^3).
\end{align}
Therefore,
\begin{align}
 \left|
 \sum_{n=0}^{M-1}e^{-j\xi_n}
 \right|^2
 =
 M^2
 -
 M\sum_{n=0}^{M-1}\xi_n^2
 +
 \left(\sum_{n=0}^{M-1}\xi_n\right)^2
 +
 \mathcal O(\|\boldsymbol{\xi}\|^3).
\end{align}
Dividing by $M^2$ gives
\begin{align}
 \nu_k
 =
 1
 -
 \frac{1}{M}\sum_{n=0}^{M-1}\xi_n^2
 +
 \frac{1}{M^2}
 \left(\sum_{n=0}^{M-1}\xi_n\right)^2
 +
 \mathcal O(\|\boldsymbol{\xi}\|^3).
\end{align}
Now define $\mathbf P \triangleq \mathbf I_M-\frac{1}{M}\mathbf 1_M\mathbf 1_M^{\mathsf T}$, where $\mathbf I_M$ is the $M \times M$ identity matrix and $\mathbf 1_M$ is the $M \times 1$ all-ones vector. Since
\begin{align}
 \|\mathbf P\boldsymbol{\xi}\|^2
 =
 \sum_{n=0}^{M-1}\xi_n^2
 -
 \frac{1}{M}
 \left(\sum_{n=0}^{M-1}\xi_n\right)^2,
\end{align}
we can write
\begin{align}
 \nu_k
 =
 1
 -
 \frac{1}{M}
 \|\mathbf P\boldsymbol{\xi}\|^2
 +
 \mathcal O(\|\boldsymbol{\xi}\|^3).
\end{align}
Using $\boldsymbol{\xi} = \mathbf J \mbf{o} + \mathcal O(\| \mbf{o} \|^2)$ inside $\lVert \mbf{P} \boldsymbol{\xi} \rVert^2$ gives
\begin{align}
 \|\mathbf P\boldsymbol{\xi}\|^2
 =
 \mbf{o} ^{\mathsf T}
 \mathbf J^{\mathsf T}\mathbf P\mathbf J
 \mbf{o}
 +
 \mathcal O(\|\mbf{o}\|^3).
\end{align}
Thus,
\begin{align}
 \nu_k
 =
 1
 -
 \frac{1}{M}
 \mbf{o}^{\mathsf T}
 \mathbf J^{\mathsf T}\mathbf P\mathbf J
 \mbf{o}
 +
 \mathcal O(\|\mbf{o}\|^3).
\end{align}
Let $\mathbf Q \triangleq \mathbf J^{\mathsf T}\mathbf P\mathbf J$. Thus, the high-gain event
$\nu_k\ge 1-\epsilon$ is, up to higher-order terms, equivalent to $\mbf{o}^{\mathsf T} \mathbf Q \mbf{o} \le M\epsilon$. This inequality defines an ellipse in the $(\Delta\theta,\Delta r)$ plane. Its semi-axis lengths scale as $\sqrt{\epsilon}$, so its area scales linearly with $\epsilon$. The cubic remainder perturbs the boundary by order $\epsilon^{3/2}$, and hence
\begin{align}\label{cdf_ap1}
 \Pr\{\nu_k\ge 1-\epsilon\}
 =
 G_M\epsilon
 +
 \mathcal O(\epsilon^{3/2}),
\end{align}
where $G_M>0$ depends on the local sampling density of $(\theta_k,r_k)$ and on the local geometry through $\mathbf Q$. Using \eqref{cdf_ap1} together with $ 1-F_\nu(1-\epsilon) = \Pr\{\nu\geq 1-\epsilon\}$, and then setting $\epsilon=1-\gamma$ proves the lemma.
